export type TokenType = 'color' | 'dimension' | 'number' | 'fontFamily' | 'fontWeight' | 'shadow' | 'string';

export interface TokenInfo {
    /** The custom property, as `--name`. */
    css: TokenName;
    /** The token's path in the DTCG files, `collection.group.name`. */
    path: string;
    /** The variable or style name in Figma. */
    figma: string;
    collection: string;
    type: TokenType | null;
    /** The default value as CSS text; an alias is `var(--other)`. */
    value: string;
    /** Values in the collection's other modes, when they differ. */
    modes?: Record<string, string>;
}

export interface CollectionInfo {
    name: string;
    slug: string;
    kind: 'variables' | 'styles';
    attribute?: string;
    modes?: string[];
    defaultMode?: string;
    theme?: true;
}

export declare const source: { figmaFile: string; exportedAt: string; exporter: string; pluginVersion?: string; importedBy?: string };
export declare const collections: readonly CollectionInfo[];
export declare const tokens: Readonly<Record<TokenName, TokenInfo>>;
